  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');
  const customer = customerResult.value;

  // Check if line with this SKU already exists
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    // Merge by increasing quantity
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : { ...line }
    );
  } else {
    // Determine discount: explicit value wins, otherwise use customer tier
    let resolvedDiscount;
    if (discountPercent !== undefined) {
      resolvedDiscount = discountPercent;
    } else {
      resolvedDiscount = TIER_DISCOUNTS[customer.tier];
    }

    // Add new line at the end
    newLines = [
      ...invoice.lines.map((line) => ({ ...line })),
      {
        sku,
        name: product.name,
        qty,
        unitPrice: product.unitPrice,
        vatRate: product.vatRate,
