test('issueInvoice resets counter for different year', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-05-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const existing = ['INV-2024-0050'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const originalStatus = invoice.status;
  assert.equal(invoice.number, undefined);

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.number, undefined);
});

test('issueInvoice preserves all invoice data', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);
  const issued = result.value;

  assert.equal(issued.customerId, 'C-003');
  assert.equal(issued.issueDate, '2024-06-15');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.lines.length, 2);
  assert.equal(issued.lines[0].sku, 'DES-HOUR');
  assert.equal(issued.lines[1].sku, 'DEV-HOUR');
});

test('issueInvoice works with modified invoices', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  // Modify the invoice
  let result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  invoice = result.value;

  result = addLine(invoice, { sku: 'COPY-HOUR', qty: 2 });
  invoice = result.value;

  // Now issue it
  const issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.status, 'issued');
  assert.equal(issued.value.lines.length, 3);
});

test('issueInvoice with multiple existing invoices from same year', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = invoiceResult.value;

  const existing = ['INV-2024-0010', 'INV-2024-0005', 'INV-2024-0015', 'INV-2024-0001'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0016');
});

